TARGET_RPM = 4000

def flip_possible(me, enemy):
    if me.airborne or me.righting or me.on_side or me.inverted:
        return False
    if me.battery_health <= 0.0:
        return False
    if me.held or me.lifted:
        return False
    fb = me.weapons.get("back")
    if fb is None or fb["health"] <= 0.0:
        return False
    if not fb.get("ready", False):
        return False
    if fb.get("shots_left", 0) <= 1:
        return False
    if enemy.airborne or enemy.righting or enemy.on_side or enemy.inverted:
        return False
    if enemy.held or enemy.lifted:
        return False
    if enemy.z > 0.02:
        return False
    if abs(enemy.vx) > 0.25 or abs(enemy.vy) > 0.25:
        return False
    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)
    if not (b > 150.0 or b < -150.0):
        return False
    if not (0.65 < d < 1.25):
        return False
    lat = d * sin(radians(b))
    if abs(lat) > 0.55:
        return False
    diff = enemy.heading - (me.heading + b + 180.0)
    diff = (diff + 180.0) % 360.0 - 180.0
    if abs(diff) > 100.0:
        return False
    return True

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)
    if flip_possible(me, enemy):
        return (0.0, 0.0)
    r = hypot(me.x, me.y)
    if r > arena.radius - 1.0:
        bc = bearing_to(0.0, 0.0)
        if bc > 10.0:
            return (0.0, 1.0)
        if bc < -10.0:
            return (1.0, 0.0)
        return (0.5, 0.5)
    d = distance_to(enemy.x, enemy.y)
    if "side" not in me.memory:
        ll = enemy.armor.get("left", 1.0)
        lr = enemy.armor.get("right", 1.0)
        if ll < lr - 0.1:
            me.memory["side"] = 1
        else:
            me.memory["side"] = -1
    side = me.memory.get("side", 1)
    last_d = me.memory.get("last_d", None)
    last_t = me.memory.get("last_t", 0.0)
    if last_d is not None and last_t > 0.0 and arena.time - last_t > 2.0:
        if d > last_d - 0.1:
            side = -side
            me.memory["side"] = side
    me.memory["last_d"] = d
    me.memory["last_t"] = arena.time
    w = me.weapons.get("front")
    direct = False
    if w is None or w["health"] <= 0.0:
        direct = True
    elif arena.time > 90.0 and d < 2.0 and w["health"] < 0.3:
        direct = True
    tx = enemy.x
    ty = enemy.y
    if not direct:
        h = radians(enemy.heading)
        off = 0.55
        if d > 2.5:
            off = 0.7
        tx = enemy.x + off * side * (-sin(h))
        ty = enemy.y + off * side * cos(h)
        rr = hypot(tx, ty)
        lim = arena.radius - 0.5
        if rr > lim:
            f = lim / rr
            tx = tx * f
            ty = ty * f
    d2 = distance_to(tx, ty)
    b2 = bearing_to(tx, ty)
    if d2 > 2.5:
        sp = 1.0
    elif d2 > 1.6:
        sp = 0.85
    else:
        sp = 0.7
    if b2 > 25.0:
        if d2 > 2.0:
            return (0.35, 1.0)
        return (0.15, 1.0)
    if b2 < -25.0:
        if d2 > 2.0:
            return (1.0, 0.35)
        return (1.0, 0.15)
    if b2 > 8.0:
        return (0.6, sp)
    if b2 < -8.0:
        return (sp, 0.6)
    return (sp, sp)

def weapons(me, enemy, arena):
    if me.airborne or me.righting:
        return None
    if me.on_side:
        if me.battery_health > 0.0:
            return self_right()
        return None
    if me.battery_health <= 0.0:
        return None
    cmds = []
    w = me.weapons.get("front")
    if w is not None and w["health"] > 0.0:
        if w["rpm"] < TARGET_RPM - 100.0:
            cmds.append(spin("front", TARGET_RPM))
    if flip_possible(me, enemy):
        cmds.append(flip("back"))
    if len(cmds) == 0:
        return None
    if len(cmds) == 1:
        return cmds[0]
    return cmds
